drop function public.get_retreat_quote_by_token(text);
create function public.get_retreat_quote_by_token(raw_token text) returns table(reference text,retreat_type_name text,retreat_format public.retreat_format,start_date date,end_date date,guest_name text,guest_count smallint,total_price numeric,deposit_required numeric,currency text,expiry_date date,notes text,payment_instructions text,quote_status public.quote_status,payment_status public.payment_status,eth_amount numeric,eth_converted_at timestamptz,payment_submitted_at timestamptz,payment_verified_at timestamptz,payment_tx_hash text,retreat_event_id uuid,event_title text) language sql stable security definer set search_path='' as $$ select q.reference,q.retreat_type_name,q.retreat_format,q.start_date,q.end_date,e.full_name,q.guest_count,q.total_price,q.deposit_required,q.currency,q.expiry_date,q.notes,q.payment_instructions,q.status,q.payment_status,q.eth_amount,q.eth_converted_at,q.payment_submitted_at,q.payment_verified_at,q.payment_tx_hash,e.retreat_event_id,ev.title from public.retreat_quotes q join public.retreat_enquiries e on e.id=q.enquiry_id left join public.retreat_events ev on ev.id=e.retreat_event_id where q.payment_token_hash=encode(extensions.digest(raw_token,'sha256'),'hex') and q.status in ('sent','accepted'); $$;
revoke all on function public.get_retreat_quote_by_token(text) from public; grant execute on function public.get_retreat_quote_by_token(text) to anon,authenticated;
